using UnityEngine; public class Bumper : MonoBehaviour { private float bounceStrength = 10f; public void Initialize(float strength) { bounceStrength = strength; } private void OnCollisionEnter(Collision collision) { if (collision.gameObject.CompareTag("Coin")) { Rigidbody rb = collision.gameObject.GetComponent<Rigidbody>(); if (rb != null) { float currentMultiplier = 1.0f; if (Time.timeScale > 1.2f) currentMultiplier = 5.0f; Vector3 direction = (collision.transform.position - transform.position).normalized; rb.linearVelocity = direction * (bounceStrength * currentMultiplier); if (SoundManager.Instance != null) SoundManager.Instance.PlayBumperHitSound(); } } } }